(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
